import 'package:audioplayers/audioplayers.dart';
import 'dart:async';

class AudioManager {
  // 단일 플레이어 예시 (공식 예제는 여러 플레이어를 사용)
  final AudioPlayer player = AudioPlayer();
  final List<StreamSubscription> _subscriptions = [];

  AudioManager() {
    // 1. ReleaseMode 설정: 재생이 완료되면 플레이어 상태를 'Stop'으로 유지합니다.
    // 이는 다음 재생 시 소스를 다시 설정할 필요 없이 바로 play()를 호출할 수 있게 합니다.
    player.setReleaseMode(ReleaseMode.stop);

    // 2. 상태 변경 스트림 구독 (공식 예제 분석)
    _subscriptions.add(
      player.onPlayerStateChanged.listen((state) {
        print('Player State Changed: $state');
        if (state == PlayerState.completed) {
          // 재생 완료 시 특정 로직 수행
          print('Audio playback completed.');
        }
      }),
    );

    // 3. 위치 변경 스트림 구독 (재생 바 업데이트 등에 사용)
    _subscriptions.add(
      player.onPositionChanged.listen((position) {
        // print('Current Position: $position');
      }),
    );
  }

  // 리소스 해제 메서드 (필수)
  void dispose() {
    for (var sub in _subscriptions) {
      sub.cancel();
    }
    player.dispose(); // 플레이어 인스턴스 자체를 해제
  }
}

