Future<void> playAsset(String assetPath) async {
  // 1. 소스 설정 (AssetSource 사용)
  await player.setSource(AssetSource(assetPath));
  // 2. 재생 시작
  await player.resume(); // setSource 후에는 resume()을 사용하거나 play()를 사용합니다.
}

Future<void> playUrl(String url) async {
  // 1. 소스 설정 (UrlSource 사용)
  await player.setSource(UrlSource(url));
  // 2. 재생 시작
  await player.resume();
}

Future<void> pause() async {
  await player.pause();
}

Future<void> stop() async {
  await player.stop();
}

Future<void> seekTo(Duration position) async {
  // 공식 예제에서 onSeekComplete 스트림을 구독했듯이, seek는 비동기적으로 완료됩니다.
  await player.seek(position);
}

Future<void> setVolume(double volume) async {
  // 0.0 (음소거) ~ 1.0 (최대)
  await player.setVolume(volume);
}

Future<void> setSpeed(double speed) async {
  // 1.0 (정상 속도)
  await player.setRate(speed);
}

import 'package:flutter/material.dart';
import 'package:audioplayers/audioplayers.dart';
import 'dart:async';

// Step 2와 3의 로직을 통합한 간단한 상태 관리 클래스
class AudioPlayerService extends ChangeNotifier {
  final AudioPlayer player = AudioPlayer();
  PlayerState _playerState = PlayerState.stopped;
  Duration _duration = Duration.zero;
  Duration _position = Duration.zero;
  StreamSubscription? _stateSubscription;
  StreamSubscription? _durationSubscription;
  StreamSubscription? _positionSubscription;

  PlayerState get playerState => _playerState;
  Duration get duration => _duration;
  Duration get position => _position;

  AudioPlayerService() {
    player.setReleaseMode(ReleaseMode.stop);
    _stateSubscription = player.onPlayerStateChanged.listen((state) {
      _playerState = state;
      notifyListeners();
    });
    _durationSubscription = player.onDurationChanged.listen((d) {
      _duration = d;
      notifyListeners();
    });
    _positionSubscription = player.onPositionChanged.listen((p) {
      _position = p;
      notifyListeners();
    });
  }

  Future<void> loadAndPlay() async {
    // 예시 애셋 경로 (실제 파일 경로로 변경 필요)
    await player.setSource(AssetSource('audio/test_audio.mp3'));
    await player.resume();
  }

  Future<void> togglePlayPause() async {
    if (_playerState == PlayerState.playing) {
      await player.pause();
    } else if (_playerState == PlayerState.paused || _playerState == PlayerState.stopped) {
      // 소스가 설정되지 않았다면 로드 후 재생
      if (_duration == Duration.zero) {
        await loadAndPlay();
      } else {
        await player.resume();
      }
    }
  }

  Future<void> seek(double value) async {
    final newPosition = Duration(milliseconds: (duration.inMilliseconds * value).round());
    await player.seek(newPosition);
  }

  @override
  void dispose() {
    _stateSubscription?.cancel();
    _durationSubscription?.cancel();
    _positionSubscription?.cancel();
    player.dispose();
    super.dispose();
  }
}

// UI 위젯 (Provider 또는 Riverpod 사용 권장)
class AudioPlayerWidget extends StatelessWidget {
  final AudioPlayerService service;

  const AudioPlayerWidget({super.key, required this.service});

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text('Duration: ${service.duration.inSeconds}s'),
        Slider(
          min: 0,
          max: service.duration.inMilliseconds.toDouble(),
          value: service.position.inMilliseconds.toDouble(),
          onChanged: (value) {},
          onChangeEnd: (value) => service.seek(value / service.duration.inMilliseconds),
        ),
        IconButton(
          iconSize: 64.0,
          icon: Icon(
            service.playerState == PlayerState.playing
                ? Icons.pause_circle
                : Icons.play_circle,
          ),
          onPressed: service.togglePlayPause,
        ),
      ],
    );
  }
}

